component.componentCode:
"use client"

// AsciiArt — "lsm", made with the 21st ASCII editor and baked
// to its exact rendered output (looping video + poster). Zero dependencies:
// one <video> that fills its parent. Drop it behind or inside your content:
// <div className="relative h-96"><AsciiArt className="absolute inset-0" /></div>
// Remix the source recipe (styles, animation, palette) in the editor:
// https://21st.dev/community/ascii/editor?from=b1aeff3c-67eb-4aae-be5d-ec9e7584945a
export function AsciiArt({ className }: { className?: string }) {
  return (
    <video
      className={className}
      src={"https://assets.21st.dev/ascii-recipes/videos/user_35tbQVU2ODM5enbRGylqcG4ZIHw/b6d770a2-13cb-4e2c-b8dc-a61b7078d61d.mp4"}
      poster={"https://assets.21st.dev/ascii-recipes/thumbnails/user_35tbQVU2ODM5enbRGylqcG4ZIHw/c7b9f2f3-f57f-46b1-a792-a176cf662698.webp"}
      autoPlay
      loop
      muted
      playsInline
      aria-label={"lsm — animated ASCII art"}
      style={{
        display: "block",
        width: "100%",
        height: "100%",
        objectFit: "cover",
      }}
    />
  )
}

